const keys = {
savedJobs: "careerconnect.savedJobs",
theme: "careerconnect.theme",
applications: "careerconnect.applications",
messages: "careerconnect.messages"
};
function readJSON(key, fallback) {
try {
const value = localStorage.getItem(key);
return value ? JSON.parse(value) : fallback;
} catch (error) {
console.warn(`CareerConnect could not read ${key}`, error);
return fallback;
}
}
function writeJSON(key, value) {
localStorage.setItem(key, JSON.stringify(value));
}
function makeId(prefix) {
if (window.crypto && typeof window.crypto.randomUUID === "function") {
return `${prefix}-${window.crypto.randomUUID()}`;
}
return `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}
export function getSavedJobIds() {
const saved = readJSON(keys.savedJobs, []);
if (!Array.isArray(saved)) {
return [];
}
return saved.map((item) => (typeof item === "string" ? item : item.id)).filter(Boolean);
}
export function getSavedJobs() {
const saved = readJSON(keys.savedJobs, []);
if (!Array.isArray(saved)) {
return [];
}
return saved
.filter((item) => item && typeof item === "object")
.map((job) => ({
...job,
savedAt: job.savedAt || new Date().toISOString()
}));
}
export function isJobSaved(jobId) {
return getSavedJobIds().includes(jobId);
}
export function toggleSavedJob(jobOrId) {
const jobId = typeof jobOrId === "string" ? jobOrId : jobOrId.id;
const savedItems = readJSON(keys.savedJobs, []);
const existingIds = new Set(getSavedJobIds());
const nextState = !existingIds.has(jobId);
let nextItems = Array.isArray(savedItems) ? savedItems.filter((item) => (typeof item === "string" ? item : item.id) !== jobId) : [];
if (nextState) {
nextItems.unshift(typeof jobOrId === "string" ? jobId : {
...jobOrId,
savedAt: new Date().toISOString()
});
}
writeJSON(keys.savedJobs, nextItems);
return { saved: nextState, ids: getSavedJobIds() };
}
export function removeSavedJob(jobId) {
const savedItems = readJSON(keys.savedJobs, []);
const nextItems = Array.isArray(savedItems)
? savedItems.filter((item) => (typeof item === "string" ? item : item.id) !== jobId)
: [];
writeJSON(keys.savedJobs, nextItems);
return nextItems.map((item) => (typeof item === "string" ? item : item.id));
}
export function getPreferredTheme() {
const stored = localStorage.getItem(keys.theme);
if (stored === "dark" || stored === "light") {
return stored;
}
return window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
}
export function setPreferredTheme(theme) {
const nextTheme = theme === "dark" ? "dark" : "light";
localStorage.setItem(keys.theme, nextTheme);
document.documentElement.dataset.theme = nextTheme;
return nextTheme;
}
export function saveApplication(application) {
const applications = readJSON(keys.applications, []);
const record = {
...application,
id: makeId("application"),
submittedAt: new Date().toISOString()
};
applications.unshift(record);
writeJSON(keys.applications, applications.slice(0, 25));
return record;
}
export function saveContactMessage(message) {
const messages = readJSON(keys.messages, []);
const record = {
...message,
id: makeId("message"),
submittedAt: new Date().toISOString()
};
messages.unshift(record);
writeJSON(keys.messages, messages.slice(0, 25));
return record;
}